package com.cretas.aims.blueprint.draftentry;
import com.cretas.aims.repository.sanitationcipdraft.SanitationCipTemplateDraftRepository;
import com.cretas.aims.service.allergenlabeldraft.AllergenLabelDraftCommand;
import com.cretas.aims.service.allergenlabeldraft.AllergenLabelDraftModels.*;
import org.springframework.stereotype.Component;
import java.util.*;
@org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name = "cretas.platform.factory-assembly.enabled", havingValue = "true", matchIfMissing = false)
@Component public class AllergenLabelDraftProposer implements CapabilityDraftProposer {
 private static final String WHY="蓝图没有过敏原声明、标签依据、换线清洁和验证证据的完整事实";
 private static List<Option> opts(Class<? extends Enum<?>> c){return Arrays.stream(c.getEnumConstants()).map(e->new Option(e.name(),e.name())).toList();}
 private static String one(Class<? extends Enum<?>> c){return String.join("、",opts(c).stream().map(Option::value).toList())+" 之一";}
 private static List<RequiredInput> declarationFields(){return List.of(RequiredInput.text("subject.kind","对象类型",WHY,"PRODUCT 或 MATERIAL",32),RequiredInput.text("subject.targetId","对象标识",WHY,"最长 64 位",64),RequiredInput.text("subject.targetSnapshotDigest","对象摘要",WHY,"SHA-256",64),RequiredInput.oneOf("allergen","过敏原",WHY,one(Allergen.class),opts(Allergen.class)),RequiredInput.oneOf("presence","存在方式",WHY,one(PresenceKind.class),opts(PresenceKind.class)).allowNull(),RequiredInput.oneOf("evidenceSource","证据来源",WHY,one(EvidenceSource.class),opts(EvidenceSource.class)).allowNull(),RequiredInput.oneOf("labelStatement","标签声明",WHY,one(LabelStatement.class),opts(LabelStatement.class)).allowNull(),RequiredInput.text("labelVersionCode","标签版本",WHY,"最长 64 位",64).allowNull(),RequiredInput.text("changeReason","变更原因",WHY,"1–500 字",500));}
 private static List<RequiredInput> changeoverFields(){return List.of(RequiredInput.text("productCode","产品",WHY,"最长 64 位",64),RequiredInput.text("routeNodeId","路线节点",WHY,"最长 128 位",128),RequiredInput.oneOf("allergen","过敏原",WHY,one(Allergen.class),opts(Allergen.class)),RequiredInput.oneOf("changeoverMethod","换线方法",WHY,one(ChangeoverMethod.class),opts(ChangeoverMethod.class)),RequiredInput.values("verifications","验证方式",WHY,"至少 1 项", "验证",1,10,RequiredInput.oneOf("verification","验证",WHY,one(ChangeoverVerification.class),opts(ChangeoverVerification.class))),RequiredInput.oneOf("responsibleRole","责任角色",WHY,one(ResponsibleRole.class),opts(ResponsibleRole.class)),RequiredInput.values("requiredEvidence","要求证据",WHY,"至少 1 项","证据",1,10,RequiredInput.oneOf("evidence","证据",WHY,one(EvidenceType.class),opts(EvidenceType.class))),RequiredInput.bool("holdUntilVerified","验证前保持",WHY,"是 / 否"),RequiredInput.text("sanitationTemplateCode","清洁模板",WHY,"最长 128 位",128),RequiredInput.text("changeReason","变更原因",WHY,"1–500 字",500));}
 private final SanitationCipTemplateDraftRepository sanitation;
 public AllergenLabelDraftProposer(SanitationCipTemplateDraftRepository sanitation){this.sanitation=sanitation;}
 public String capabilityId(){return AllergenLabelDraftCommand.CAPABILITY_ID;}
 public Proposed propose(Source s){var upstream=UpstreamDraftPins.latestSanitation(sanitation,s).orElse(null);if(upstream==null)return Proposed.blocked("UPSTREAM_MISSING","过敏原标签必须绑定本蓝图同一版本的清洁消毒草稿，当前没有可验证的上游草稿","先写清洁消毒草稿");var req=new DraftRequest(s.factoryId(),s.blueprint().getId(),s.blueprint().getVersion(),s.sourceDigest(),new SanitationTemplatePin(upstream.getId(),upstream.getDesiredDigest()),List.of(),List.of(),null,null,0L);var inputs=List.of(RequiredInput.list("declarations","过敏原声明",WHY,"至少 1 条，最多 500 条，每条字段均须填写","声明",1,500,declarationFields()),RequiredInput.list("changeovers","换线清洁",WHY,"至少 1 条，最多 200 条，每条字段均须填写","换线",1,200,changeoverFields()));return Proposed.single(capabilityId(),"过敏原标签",req,inputs,List.of(new Evidence("sanitation",upstream.getId()+" / "+upstream.getDesiredDigest())));}
}
